insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_eng3_v1'
from (values
('110.38.c.2.A',3,'A junior needs the legal meaning of ''tort'' for a civics paper. Which resource fits best?','["a specialized legal dictionary", "a rhyming dictionary", "a cookbook index", "a road atlas"]'::jsonb,0,'Specialized dictionaries define field-specific terms.','original'),
('110.38.c.2.A',3,'Which resource would a student use to find the history of a word''s meaning over centuries?','["a style sheet", "an etymological dictionary", "a map legend", "a phone directory"]'::jsonb,1,'Etymological dictionaries trace word history.','original'),
('110.38.c.2.B',3,'A speaker calls a policy ''a bold experiment'' while a critic calls it ''a reckless gamble.'' What is the difference?','["their rhyme", "their length", "their connotations", "their denotations, which differ completely"]'::jsonb,2,'The words describe the same thing with different emotional weight.','original'),
('110.38.c.2.B',4,'In ''The mill''s smoke was a gray quilt over the town,'' what kind of meaning does ''quilt'' have?','["technical", "literal", "denotative only", "figurative"]'::jsonb,3,'Smoke is compared to a quilt.','original'),
('110.38.c.2.B',3,'Which word has the most neutral connotation for describing a person who stays home often?','["homebody", "shut-in", "recluse", "hermit"]'::jsonb,0,'The others suggest isolation.','original'),
('110.38.c.2.C',3,'A historian refers to the ''laissez-faire'' approach of a government. What does the phrase suggest?','["constant war", "a hands-off policy toward the economy", "heavy taxation", "strict control"]'::jsonb,1,'French for ''let do.''','original'),
('110.38.c.2.C',3,'What does the Latin phrase ''habeas corpus'' protect against?','["double taxation", "theft of property", "unlawful imprisonment without a hearing", "libel"]'::jsonb,2,'It requires a person be brought before a court.','original'),
('110.38.c.2.C',4,'A critic describes a novel as a ''magnum opus.'' What is being said?','["it was never finished", "it is the shortest work", "it is an early draft", "it is the author''s greatest work"]'::jsonb,3,'Latin for ''great work.''','original'),
('110.38.c.4.F',3,'Passage: ''Though the fields were green, Amos stood at the fence and counted the empty seed sacks twice.'' What can be inferred?','["he is worried about the coming season", "he is leaving the farm happily", "he is planning a party", "he has a large surplus"]'::jsonb,0,'Counting empty sacks twice signals worry.','original'),
('110.38.c.4.F',4,'A narrator in a 1930s story notes that ''the line outside the bakery wound around the block, and nobody spoke.'' What does this imply about the setting?','["the bakery is giving a party", "times are hard and people are desperate", "the town is on vacation", "the baker is famous for pastries"]'::jsonb,1,'Silent crowds waiting suggest hardship.','original'),
('110.38.c.4.G',3,'To evaluate which details support a key idea in a speech, a reader should ask what?','["which detail has the most adjectives", "which detail is the longest", "which details directly connect to the speaker''s main point", "which detail is first"]'::jsonb,2,'Evaluate relevance to the central idea.','original'),
('110.38.c.4.G',4,'A writer includes a statistic about city air quality inside an essay on lung disease. How should a reader treat the statistic?','["as irrelevant", "as a rhyme", "as the essay''s title", "as a supporting detail for the essay''s claim"]'::jsonb,3,'Statistics back up key ideas.','original'),
('110.38.c.4.H',4,'A reader compares a diary entry from a pioneer and a government land record from the same year. What does combining them allow?','["a fuller understanding than either source alone", "proof the diary is false", "no new understanding", "a replacement of both sources"]'::jsonb,0,'Synthesis builds a richer picture.','original'),
('110.38.c.4.H',3,'When two sources disagree on a date, what should a researcher do?','["ignore both", "check additional reliable sources to resolve it", "pick the one with fewer words", "average the dates"]'::jsonb,1,'Cross-checking resolves conflict.','original'),
('110.38.c.4.I',3,'A reader keeps losing track of characters in a dense novel. Which adjustment helps most?','["ignoring names", "skipping every chapter", "making a character list while reading", "reading with the sound off"]'::jsonb,2,'Notes support comprehension.','original'),
('110.38.c.4.I',3,'A reader reaches a sentence with several unfamiliar terms. What is a sound first step?','["skip all sentences like it", "stop reading permanently", "guess randomly", "use context clues and then consult a reference"]'::jsonb,3,'Monitor and adjust.','original'),
('110.38.c.5.B',4,'A student compares how two American poems depict the frontier, one hopeful and one grim. What is being compared?','["the poets'' attitudes and techniques", "the font in each book", "the number of pages", "the publishers"]'::jsonb,0,'Cross-text comparison focuses on ideas and craft.','original'),
('110.38.c.5.B',3,'A strong response that compares two texts usually does what?','["retells one text only", "identifies similarities and differences with evidence", "lists only similarities with no evidence", "avoids quotations"]'::jsonb,1,'Comparison needs evidence.','original'),
('110.38.c.5.C',3,'A student writes, ''The narrator''s tone shifts from hope to bitterness,'' then adds a quotation. What should follow the quotation?','["another quotation without comment", "a new unrelated topic", "an explanation of how it shows the shift", "the title again"]'::jsonb,2,'Original commentary connects evidence to claim.','original'),
('110.38.c.5.C',4,'Which sentence contains original commentary about a quotation?','["''The author wrote the line.''", "''Page 12.''", "''The text says \"cold hearth.\"''", "''This image of a cold hearth suggests the family''s loss of warmth and security.''"]'::jsonb,3,'Commentary interprets the evidence.','original'),
('110.38.c.5.D',3,'Which is a faithful paraphrase of ''The orator''s words ignited the crowd''?','["The speaker''s words stirred the audience to excitement.", "The speaker was silent.", "The audience left.", "The crowd burned down the hall."]'::jsonb,0,'A paraphrase keeps meaning in new words.','original'),
('110.38.c.5.D',3,'A summary of a speech should keep what?','["the speaker''s gestures", "its main points in the original order", "every anecdote", "the reader''s opinion only"]'::jsonb,1,'Summaries maintain logical order.','original'),
('110.38.c.5.F',3,'In a response about the Constitution, which word is the most precise for ''an official change to the document''?','["poster", "doodle", "amendment", "suggestion"]'::jsonb,2,'Content vocabulary improves accuracy.','original'),
('110.38.c.5.F',3,'Which word is academic vocabulary for ''to explain in detail''?','["skip", "shrug", "mumble", "elaborate"]'::jsonb,3,'Academic terms suit formal responses.','original'),
('110.38.c.5.G',3,'''He never mentioned the war again, though he flinched at every loud noise.'' What is implied?','["the war left him with lasting distress", "he wrote a book on it", "he loves loud sounds", "the war was a game"]'::jsonb,0,'Behavior implies meaning.','original'),
('110.38.c.5.G',3,'Which statement describes an explicit meaning?','["a mood suggested by weather", "a narrator directly states that the farm failed", "an unspoken attitude", "a hint in a character''s pause"]'::jsonb,1,'Explicit meaning is stated outright.','original'),
('110.38.c.5.J',4,'An editorial claims ''everyone supports the new law'' but cites a poll of 20 people from one club. What is a reasonable challenge?','["polls are never valid", "the editorial is too short", "the sample is too small and unrepresentative", "the law is new"]'::jsonb,2,'A poor sample weakens the claim.','original'),
('110.38.c.5.J',3,'A defense of an author''s claim is strongest when it includes what?','["a longer title", "a different topic", "a loud tone", "relevant evidence cited from the text"]'::jsonb,3,'Evidence defends a claim.','original'),
('110.38.c.6.A',3,'A pioneer family loses a crop but is rescued by neighbors. Which theme is developed through the plot?','["community can sustain people through hardship", "neighbors cause trouble", "hardship is imaginary", "crops never fail"]'::jsonb,0,'Rescue resolves conflict and signals theme.','original'),
('110.38.c.6.A',4,'How can two American novels about ambition show similar themes?','["through identical titles", "through characters whose pursuit of success has costs", "through matching page counts", "through the same cover art"]'::jsonb,1,'Compare character and plot development.','original'),
('110.38.c.6.B',3,'A character who dreams of a better life and reinvents himself is sometimes called what, in American literature?','["a footnote", "a glossary entry", "a self-made figure", "a stock extra"]'::jsonb,2,'The self-made figure is a recurring type.','original'),
('110.38.c.6.B',4,'An author shows a character''s honesty through repeated small acts, such as returning extra change. What method is this?','["direct characterization", "a soliloquy", "an epigraph", "indirect characterization"]'::jsonb,3,'Actions reveal traits without stating them.','original'),
('110.38.c.6.C',3,'A scene in which a mother hides her tears while packing a suitcase mostly contributes what to the plot?','["emotional stakes for the departure", "the story''s rhyme", "the thesis", "the setting''s name"]'::jsonb,0,'Isolated scenes add weight to plot.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_eng3_v1'
from (values
('110.38.c.6.C',4,'A quiet scene before a trial shows a lawyer rehearsing alone. How does it contribute to the whole?','["it resolves the conflict", "it builds tension and reveals his doubts", "it is unrelated", "it introduces a rhyme scheme"]'::jsonb,1,'Scenes support the larger structure.','original'),
('110.38.c.6.D',3,'A novel set in the Jim Crow South shows characters limited by unjust laws. How does the setting influence the plot?','["the setting has no effect", "the plot is only about weather", "the laws create obstacles and shape the conflict", "the laws are invisible"]'::jsonb,2,'Historical context shapes events.','original'),
('110.38.c.6.D',4,'A story set during the Great Depression emphasizes sharing scarce food. What does the setting help develop?','["a comedy of manners", "a theme about abundance", "a rhyme scheme", "a theme about survival and generosity"]'::jsonb,3,'Setting influences theme.','original'),
('110.38.c.7.A',3,'Who wrote ''The Scarlet Letter''?','["Nathaniel Hawthorne", "Mark Twain", "Edgar Allan Poe", "Herman Melville"]'::jsonb,0,'A classic of American Romanticism.','original'),
('110.38.c.7.A',3,'Which novel by F. Scott Fitzgerald explores the American Dream in the 1920s?','["Walden", "The Great Gatsby", "Moby-Dick", "The Grapes of Wrath"]'::jsonb,1,'A key novel of the Jazz Age.','original'),
('110.38.c.7.A',3,'Which author wrote the Transcendentalist essay ''Self-Reliance''?','["Emily Dickinson", "Walt Whitman", "Ralph Waldo Emerson", "Robert Frost"]'::jsonb,2,'Emerson championed individualism.','original'),
('110.38.c.7.A',3,'Which literary period is associated with Harlem during the 1920s?','["Colonial America", "the Beat era", "the Gothic revival", "the Harlem Renaissance"]'::jsonb,3,'A flowering of Black arts and letters.','original'),
('110.38.c.7.A',4,'Which poet is known for unconventional punctuation and short, slant-rhymed poems such as ''Hope is the thing with feathers''?','["Emily Dickinson", "Carl Sandburg", "Langston Hughes", "Robert Frost"]'::jsonb,0,'Dickinson used dashes and slant rhyme.','original'),
('110.38.c.7.B',3,'Free verse poetry often uses which feature to create rhythm?','["a required refrain", "line breaks and repetition rather than regular meter", "strict iambic pentameter", "fixed rhyme pairs"]'::jsonb,1,'Free verse lacks fixed meter and rhyme.','original'),
('110.38.c.7.B',4,'A poem with alternating end rhymes in a pattern ABAB is made of what?','["a couplet", "a limerick", "a quatrain with an alternating rhyme scheme", "a haiku"]'::jsonb,2,'ABAB is a common quatrain pattern.','original'),
('110.38.c.7.B',3,'Repeating consonant sounds at the beginning of nearby words is called what?','["assonance", "refrain", "meter", "alliteration"]'::jsonb,3,'Alliteration repeats initial consonants.','original'),
('110.38.c.7.C',3,'A play''s narrator steps out of the scene to speak to the audience about the story. What dramatic convention is this?','["direct address", "a stage curtain", "an index", "a footnote"]'::jsonb,0,'Direct address breaks the fourth wall.','original'),
('110.38.c.7.C',4,'A playwright mocks politicians by exaggerating their flaws. Which genre convention is used?','["ode", "satire", "epic", "elegy"]'::jsonb,1,'Satire uses exaggeration for critique.','original'),
('110.38.c.7.D.i',3,'Which thesis best fits an analytical essay on a short story?','["''Short stories are fun.''", "''I will write about a short story.''", "''Through the use of a shifting setting, the author shows the narrator''s growing fear.''", "''The story has a setting.''"]'::jsonb,2,'A thesis makes an arguable claim with focus.','original'),
('110.38.c.7.D.i',4,'Where in an essay do pertinent examples belong?','["only in the title", "only in the introduction", "after the conclusion", "in body paragraphs that support the thesis"]'::jsonb,3,'Examples develop each point.','original'),
('110.38.c.7.D.ii',3,'If an essay''s thesis is about how a hero changes, which organization best supports it?','["following the hero''s change in sequence", "describing the cover", "listing rhymes alphabetically", "random events"]'::jsonb,0,'Structure should serve the thesis.','original'),
('110.38.c.7.E.i',3,'Which sentence is an arguable claim?','["''Parks have grass.''", "''Public parks should receive more city funding than parking lots.''", "''Cities have budgets.''", "''Parking lots are gray.''"]'::jsonb,1,'A claim takes a debatable position.','original'),
('110.38.c.7.E.i',3,'Using statistics and logical reasoning to persuade is an appeal to what?','["pathos", "ethos", "logos", "kairos"]'::jsonb,2,'Logos appeals to reason.','original'),
('110.38.c.7.E.ii',4,'A writer says, ''I agree that the fee is burdensome, but waiving it entirely would end the program.'' This sentence combines a concession with what?','["a summary", "a thesis only", "an anecdote", "a rebuttal"]'::jsonb,3,'It grants a point, then counters.','original'),
('110.38.c.7.E.ii',3,'Which kind of evidence is an expert''s testimony?','["authoritative evidence", "invented evidence", "visual evidence", "statistical evidence"]'::jsonb,0,'Experts lend authority.','original'),
('110.38.c.7.E.iii',3,'A writer addressing busy employees keeps an argument short and focused. What does this show?','["ignoring the reader", "attention to the reader''s needs", "wanting to hide the claim", "a lack of evidence"]'::jsonb,1,'Audience awareness shapes style.','original'),
('110.38.c.7.F',3,'Which element of a documentary film is part of its multimodal design?','["only silence", "only printed text", "narration paired with archival images", "a table of contents"]'::jsonb,2,'Documentaries combine modes.','original'),
('110.38.c.7.F',3,'Why do many websites add alt text to images?','["to add rhyme", "to slow loading", "to hide captions", "to describe them for readers who cannot see them"]'::jsonb,3,'Alt text improves access.','original'),
('110.38.c.8.A',3,'A speech given at a veterans'' memorial honors the fallen with solemn words. What is the likely purpose?','["to commemorate and inspire respect", "to sell a product", "to confuse", "to give directions"]'::jsonb,0,'Commemorative speeches honor.','original'),
('110.38.c.8.A',3,'A pamphlet from 1917 urges citizens to buy war bonds. What is its purpose?','["to describe weather", "to persuade readers to act", "to teach grammar", "to entertain"]'::jsonb,1,'Propaganda persuades.','original'),
('110.38.c.8.A',4,'A magazine feature uses plain language and many photos to explain tax forms. Who is the intended audience?','["no one", "toddlers", "general readers", "tax lawyers only"]'::jsonb,2,'Accessible language signals a broad audience.','original'),
('110.38.c.8.B',3,'An essay explains the stages of the Dust Bowl in the order they occurred. What structure does it use?','["spatial order", "compare and contrast", "classification", "chronological order"]'::jsonb,3,'Time order structures events.','original'),
('110.38.c.8.B',4,'A text describes the benefits and costs of a policy and weighs them. What structure is dominant?','["compare and contrast", "chronological", "alphabetical", "descriptive"]'::jsonb,0,'Weighing options compares.','original'),
('110.38.c.8.C',3,'A map in a history chapter showing territorial changes helps the reader do what?','["find the author''s name", "visualize changes across places", "count syllables", "decode rhymes"]'::jsonb,1,'Maps show spatial change.','original'),
('110.38.c.8.C',3,'Why might an author use a pull quote in a magazine feature?','["to hide the article", "to replace the title", "to highlight a key line and draw readers in", "to list sources"]'::jsonb,2,'Pull quotes emphasize ideas.','original'),
('110.38.c.8.D',4,'An author describes factory workers as ''cogs in an endless machine.'' How does this language shape perception?','["it suggests workers are lazy", "it has no effect", "it suggests workers are rich", "it suggests workers are dehumanized"]'::jsonb,3,'Metaphor affects readers'' views.','original'),
('110.38.c.8.D',3,'A writer chooses ''pioneer'' rather than ''invader'' to describe settlers. What does the choice influence?','["the reader''s sympathy toward the settlers", "the page margin", "the length of the sentence", "the rhyme"]'::jsonb,0,'Diction affects perception.','original'),
('110.38.c.8.E',3,'A man who sells fire extinguishers has his shop burn down. What kind of irony is this?','["sarcasm", "situational irony", "dramatic irony", "verbal irony"]'::jsonb,1,'The outcome contradicts expectation.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
